package jp.tapmarker;
import java.io.*;import java.util.*;import java.util.zip.*;

/** Recorded RGB scene identity, confirmed controls and display-local coordinate replay. */
public final class Video6662ReplayTest {
 static final String P=CoinPreset.P;static int checks;static Map<String,float[]> refs;static Map<String,VirtualPresetProfileTest.Image> frames=new LinkedHashMap<>();
 static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
 static void load()throws Exception{refs=VirtualPresetProfileTest.canonical("tests/video6662-references.bin");try(DataInputStream in=new DataInputStream(new GZIPInputStream(new FileInputStream("tests/video6662-replay.bin.gz")))){int n=in.readInt();for(int i=0;i<n;i++)frames.put(in.readUTF(),new VirtualPresetProfileTest.Image(in));check(in.read()==-1,"all recorded pixels read");}}
 static class Runtime {
  PhaseEngine e=new PhaseEngine();AdaptiveLayout layout;Map<String,float[]> last;long clock;
  Runtime(){check(CoinPreset.install(e,refs),"coin graph installed");e=e.runtimeCopy();e.strictRuntime=true;layout=AdaptiveLayout.install(e,CoinPreset.APP,refs,Collections.emptyMap());check(layout instanceof CoinLayout,"same runtime entry point selects coin layout");AdCloseAutomaton.install(e,CoinPreset.APP);check(e.validate().isEmpty(),"all coin states, controls and arrows are valid");}
  Map<String,float[]> sample(String frame,long now){VirtualPresetProfileTest.Image im=frames.get(frame);clock=Math.max(clock,now);last=layout.sample(e.activeRegions(),im.width,im.height,im,now);return last;}
  PhaseEngine.Watch event(String state,String first,String second,long now){e.enter(P+state,0);e.observe(sample(first,now),now);check(e.poll()==null,"first observed image cannot commit a transition: "+state+" / "+first);e.observe(sample(second,now+350),now+350);return e.poll();}
  PhaseEngine.Watch expect(String state,String first,String second,String target,int action,long now){PhaseEngine.Watch w=event(state,first,second,now);check(w!=null&&w.nextPhase.equals(P+target)&&w.action==action,"observed coin branch "+state+" / "+first+" -> "+target+" actual="+(w==null?e.diagnostic:w.id));return w;}
 }
 static void knownScenes(){
  for(String state:new String[]{"check","ad","verify"})for(String[] row:new String[][]{{"0.00","3.00","main"},{"6.00","8.00","main"},{"8.00","8.50","main"},{"32.00","34.00","main"},{"1.00","4.25","fever"},{"4.00","4.25","fever"},{"14.00","22.00","bonus"}}){Runtime r=new Runtime();r.expect(state,row[0],row[1],row[2],PhaseEngine.WAIT,100);check(RecoveryRequest.visibleBranch(r.e,r.last),"known game scene takes precedence over a pending recovery: "+row[0]);}
  for(String[] row:new String[][]{{"0.00","3.00"},{"6.00","8.00"},{"8.00","8.50"}}){Runtime r=new Runtime();check(r.event("main",row[0],row[1],100)==null,"moving coins, changing stage colours and numbers keep main state: "+row[0]);check(CoinPreset.playable(r.e,r.last),"visible button permits main markers: "+row[1]);}
  Runtime r=new Runtime();r.expect("main","6.50","6.55","clear",PhaseEngine.WAIT,100);r=new Runtime();r.expect("main","1.00","4.25","fever",PhaseEngine.WAIT,100);r=new Runtime();r.expect("main","14.00","22.00","bonus",PhaseEngine.WAIT,100);r=new Runtime();r.expect("fever","6.00","8.00","check",PhaseEngine.WAIT,100);
 }
 static void bonusJourney(){
  Runtime r=new Runtime();PhaseEngine.Watch w=r.expect("main","14.00","22.00","bonus",PhaseEngine.WAIT,100);r.e.finish(w,500);check(!CoinPreset.playable(r.e,r.last),"dim dialog never permits main-loop markers");
  w=r.expect("bonus","14.00","22.00","verify",PhaseEngine.CENTER,100);VirtualPresetProfileTest.Image im=frames.get("22.00");check(r.e.confirmsAction(w,r.e.current,r.e.epoch,r.sample("22.00",1200)),"fresh paired dialog preflight confirms start");float[] p=r.layout.point(w,r.last,im.width,im.height);check(p!=null&&p[0]/im.width>.32f&&p[0]/im.width<.68f&&p[1]/im.height>.77f&&p[1]/im.height<.80f,"tap is inside this dialog's this-is-fine start, below its CM button: "+Arrays.toString(p));r.e.finish(w,1300);check(!CoinPreset.playable(r.e,r.last),"tap completion alone cannot authorize main-loop input");
  w=r.expect("verify","32.00","34.00","main",PhaseEngine.WAIT,100);r.e.finish(w,500);check(CoinPreset.playable(r.e,r.last),"only returned home pixels enable markers");
  r=new Runtime();w=r.expect("bonus","14.00-native","22.00-native","verify",PhaseEngine.CENTER,100);im=frames.get("14.00-native");p=r.layout.point(w,r.last,im.width,im.height);check(p!=null&&p[1]>1480&&p[1]<1535,"native dialog tap lies in the recorded start label");
 }
 static void ads(){
  for(String[] row:new String[][]{{"12.00","12.00"},{"28.00","30.00"}}){Runtime r=new Runtime();PhaseEngine.Watch w=r.expect("ad",row[0],row[1],"ad",PhaseEngine.CENTER,100);VirtualPresetProfileTest.Image im=frames.get(row[1]);check(w.regionId.equals(AdCloseAutomaton.RIGHT),"only ready corner control is selected");float[] p=r.layout.point(w,r.last,im.width,im.height);check(p!=null&&p[0]/im.width>.90f&&p[0]/im.width<.96f&&p[1]/im.height>.09f&&p[1]/im.height<.13f,"actual ad X/next coordinate includes the recorded black top margin: "+Arrays.toString(p));check(!CoinPreset.playable(r.e,r.last),"ad cannot receive main-loop taps");}
  for(String frame:new String[]{"2.00","10.00","16.00","18.00","24.00"}){Runtime r=new Runtime();check(r.event("ad",frame,frame,100)==null,"web page/video/countdown is not a ready close control or game: "+frame);check(!RecoveryRequest.visibleBranch(r.e,r.last),"unknown ad does not falsely cancel recovery: "+frame);}
  Runtime r=new Runtime();PhaseEngine.Watch w=r.expect("ad","12.00-native","12.00-native","ad",PhaseEngine.CENTER,100);float[] point=r.layout.point(w,r.last,856,1920);check(point!=null&&point[0]>775&&point[0]<810&&point[1]>190&&point[1]<230,"grey-circle white X at native resolution");
  r=new Runtime();w=r.expect("ad","30.00-native","30.00-native","ad",PhaseEngine.CENTER,100);check(w!=null,"native ready double-chevron also matches");
  r=new Runtime();r.e.enter(P+"ad",0);r.e.observe(r.sample("10.00",31000),31000);w=r.e.poll();check(w!=null&&w.action==PhaseEngine.RETURN_APP&&w.nextPhase.equals(P+"verify"),"persisting unrecognized ad uses registered app return without a guessed click");
 }
 static void missionsAndBoosts(){
  Runtime notice=new Runtime();check(notice.event("main","32.00","34.00",100)==null&&CoinPreset.playable(notice.e,notice.last),"recorded red badge does not interrupt unfinished coin dropping");
  for(String state:new String[]{"check","ad","verify"})for(String[] row:new String[][]{{"3.50","14.30","missions"},{"4.80","5.30","missions"},{"3.75","14.45","reward"},{"8.30","31.00","boost-rare"},{"2.30","2.30","boost-pocket"}}){Runtime r=new Runtime();r.expect(state,row[0],row[1],row[2],PhaseEngine.WAIT,100);check(!CoinPreset.playable(r.e,r.last),"mission and boost dialogs never permit main markers");}
  Runtime r=new Runtime();PhaseEngine.Watch w=r.expect("missions","3.50","14.30","claim-wait",PhaseEngine.CENTER,100);VirtualPresetProfileTest.Image im=frames.get("14.30");float[] p=r.layout.point(w,r.last,im.width,im.height);check(w.id.equals(P+"get-tap")&&p!=null&&p[0]/im.width>.73f&&p[0]/im.width<.87f&&p[1]/im.height>.40f&&p[1]/im.height<.43f,"individual orange Get centre is selected before Play");
  List<PhaseEngine.Region> plan=ScanPlan.select(r.e,w.regionId,false);check(plan.size()==2&&plan.get(1).id.equals(P+"missions"),"Get preflight retains its own mission heading dependency");
  Map<String,float[]> fresh=r.layout.sample(plan,im.width,im.height,frames.get("22.25"),1200);check(r.e.confirmsAction(w,r.e.current,r.e.epoch,fresh),"holdout Get pixels confirm immediate preflight");fresh=r.layout.sample(plan,im.width,im.height,frames.get("22.30"),1550);check(!r.e.confirmsAction(w,r.e.current,r.e.epoch,fresh)&&r.layout.point(w,fresh,im.width,im.height)==null,"dim loading spinner cancels Get input");
  w=r.expect("claim-wait","3.75","14.45","reward",PhaseEngine.WAIT,100);r.e.finish(w,500);check(!r.e.phases.get(r.e.current).markersDuring,"claim completion still requires closing reward and Play");
  w=r.expect("reward","3.75","14.45","mission-opening",PhaseEngine.CENTER,100);im=frames.get("14.45");p=r.layout.point(w,r.last,im.width,im.height);check(p!=null&&p[1]/im.height>.556f&&p[1]/im.height<.577f,"reward uses its own Close centre");
  r.expect("mission-opening","4.80","5.30","missions",PhaseEngine.WAIT,100);w=r.expect("missions","4.80","5.30","mission-verify",PhaseEngine.CENTER,100);check(w.id.equals(P+"mission-play"),"unclaimed reward absent allows recorded first-row Play");r.e.finish(w,500);check(!CoinPreset.playable(r.e,r.last),"sending Play alone does not prove the game returned");w=r.expect("mission-verify","20.00","34.00","main",PhaseEngine.WAIT,100);r.e.finish(w,500);check(CoinPreset.playable(r.e,r.last),"returned game pixels authorize main loop after Play");
  for(String state:new String[]{"mission-opening","mission-ad"}){r=new Runtime();r.expect(state,"12.50","22.50","mission-tap",PhaseEngine.WAIT,100);check(!r.e.phases.get(r.e.current).markersDuring,"an incomplete mission routes to reopening instead of main");}
  r=new Runtime();w=r.expect("mission-tap","0.00","3.00","mission-opening",PhaseEngine.CENTER,100);im=frames.get("3.00");p=r.layout.point(w,r.last,im.width,im.height);check(p!=null&&p[0]/im.width>.39f&&p[0]/im.width<.48f&&p[1]/im.height>.09f&&p[1]/im.height<.106f,"mission tap lies in the observed header button");
  for(String[] row:new String[][]{{"boost-rare","8.30","31.00"},{"boost-pocket","2.30","2.30"}}){r=new Runtime();w=r.expect(row[0],row[1],row[2],"reward-ad",PhaseEngine.CENTER,100);im=frames.get(row[2]);p=r.layout.point(w,r.last,im.width,im.height);float top=row[2].equals("31.00")?.712f:.739f,bottom=row[2].equals("31.00")?.742f:.776f;check(p!=null&&p[1]/im.height>top&&p[1]/im.height<bottom,"boost uses its own observed CM control after dialog scaling: "+Arrays.toString(p));}
  r=new Runtime();r.expect("reward-ad","28.00","30.00","reward-ad",PhaseEngine.CENTER,100);check(r.event("reward-ad","18.00","18.00",100)==null,"reward ad countdown is allowed to finish");r.expect("mission-ad","12.00","12.00","mission-ad",PhaseEngine.CENTER,100);
  for(String state:new String[]{"missions","reward","claim-wait","mission-ad","mission-verify"}){check(CoinPreset.recoveryState(P+state).equals(P+"mission-ad")&&CoinPreset.recoveryTarget(P+state).equals(P+"mission-opening"),"mission recovery target retains pending work: "+state);}
  check(CoinPreset.recoveryTarget(P+"ad").equals(P+"verify"),"ordinary recovery keeps ordinary display verification");
  r=new Runtime();r.e.enter(P+"missions",0);im=frames.get("14.30-native");Map<String,float[]> sample=r.layout.sample(r.e.activeRegions(),im.width,im.height,im,1000);w=r.e.rule(P+"get-tap");check(r.e.confirmsAction(w,r.e.current,r.e.epoch,sample),"native Get detection agrees with half-size replay");
  final VirtualPresetProfileTest.Image get=im,play=frames.get("14.50");final int width=im.width,height=im.height;final float shift=.183f;final int[] source=RegionMath.bounds(new float[]{.67f,.389f,.925f,.437f},width,height);
  RegionSampler.Pixels moved=(x,y)->{int py=y-Math.round(shift*height);if(x>=source[0]&&x<source[2]&&py>=source[1]&&py<source[3])return get.get(x,py);return play.get(Math.min(play.width-1,x*play.width/width),Math.min(play.height-1,y*play.height/height));};
  r=new Runtime();r.e.enter(P+"missions",0);sample=r.layout.sample(r.e.activeRegions(),width,height,moved,1000);r.e.observe(sample,1000);check(r.e.poll()==null,"new second-row Get also requires two frames");sample=r.layout.sample(r.e.activeRegions(),width,height,moved,1350);r.e.observe(sample,1350);w=r.e.poll();check(w!=null&&w.id.equals(P+"get-tap"),"synthetically moved second-row Get blocks first-row Play");p=r.layout.point(w,sample,width,height);check(p!=null&&Math.abs(p[1]/height-(.4125f+shift))<.01f,"each visible Get is tapped at its own actual centre");
 }
 static void coordinatesAndNegatives(){
  VirtualPresetProfileTest.Image im=frames.get("34.00-native");Runtime r=new Runtime();r.e.enter(P+"verify",0);
  long now=10000;for(float[] t:new float[][]{{1,1,0,0},{1,.90f,0,.06f},{.94f,.86f,.03f,.08f}}){now+=2000;
   final int width=642,height=1440;RegionSampler.Pixels inset=(x,y)->{float sx=(x/(float)width-t[2])/t[0],sy=(y/(float)height-t[3])/t[1];if(sx<0||sx>=1||sy<0||sy>=1)return 0xff111820;return im.get(Math.min(im.width-1,(int)(sx*im.width)),Math.min(im.height-1,(int)(sy*im.height)));};
   r.e.enter(P+"verify",now-1000);Map<String,float[]> samples=r.layout.sample(r.e.activeRegions(),width,height,inset,now);r.e.observe(samples,now);check(r.e.poll()==null,"inset layout requires a second fresh frame: "+Arrays.toString(t)+" "+r.e.diagnostic);samples=r.layout.sample(r.e.activeRegions(),width,height,inset,now+350);r.e.observe(samples,now+350);PhaseEngine.Watch w=r.e.poll();check(w!=null&&w.nextPhase.equals(P+"main"),"normal/virtual inset geometry resolves the same state: "+Arrays.toString(t));r.e.finish(w,now+400);float[] p=samples.get(AdaptiveLayout.MAIN);check(p!=null&&Math.abs(p[0]/width-(.5f*t[0]+t[2]))<.025f&&Math.abs(p[1]/height-(CoinPreset.MAIN_Y*t[1]+t[3]))<.025f,"main marker follows the sampled window, not preview pixels");
  }
  for(String frame:new String[]{"14.00","22.00","10.00","30.00"}){r=new Runtime();r.e.enter(P+"main",0);r.sample(frame,1000);check(!CoinPreset.playable(r.e,r.last),"different/covered scene blocks markers immediately: "+frame);}
  r=new Runtime();r.e.enter(P+"bonus",0);int[] cut=RegionMath.bounds(CoinPreset.BONUS,im.width,im.height);VirtualPresetProfileTest.Image dialog=frames.get("14.00-native");RegionSampler.Pixels noTitle=(x,y)->x>=cut[0]&&x<cut[2]&&y>=cut[1]&&y<cut[3]?0xff101820:dialog.get(x,y);Map<String,float[]> samples=r.layout.sample(r.e.activeRegions(),dialog.width,dialog.height,noTitle,1000);PhaseEngine.Watch start=r.e.rule(P+"start-tap");check(!r.e.confirmsAction(start,r.e.current,r.e.epoch,samples),"start text without its own dialog heading cannot authorize input");check(r.layout.point(start,samples,dialog.width,dialog.height)==null,"no guessed centre for an unconfirmed dialog");
  for(String state:new String[]{"main","fever","bonus"}){r=new Runtime();r.e.enter(P+state,0);float area=0;for(PhaseEngine.Region region:r.e.activeRegions()){float[] b=region.bounds;if(AdCloseAutomaton.handles(region.id))check((b[2]-b[0])*(b[3]-b[1])<=.019f,"ad interruption corners remain sparse");else area+=(b[2]-b[0])*(b[3]-b[1]);}check(area<.10f,"ordinary state has only sparse declared regions: "+state);}
 }
 static void graphOwnership(){PhaseEngine e=new PhaseEngine();CoinPreset.install(e,refs);PhaseEngine custom=e.runtimeCopy();custom.regions.get(P+"home").bounds[0]+=.01f;check(AdaptiveLayout.install(custom,CoinPreset.APP,refs,Collections.emptyMap())==null,"custom ROI edits are retained");check(CoinPreset.install(e,refs)==false,"installing again cannot duplicate states or arrows");for(PhaseEngine.Phase state:e.phases.values()){check(state.markersDuring==(state.id.equals(P+"main")||state.id.equals(P+"fever")),"only game phases enable burst input");for(PhaseEngine.Watch w:state.watches)check(w.historyRule.isEmpty()&&w.historyPhase.isEmpty(),"no hidden history conditions");}check(PresetRegistry.supports(CoinPreset.APP)&&PresetRegistry.asset(CoinPreset.APP).equals("coin-preset.json")&&PresetRegistry.verify(CoinPreset.APP).equals(P+"verify"),"selection, evidence and recovery agree on coin app identity");}
 public static void main(String[] args)throws Exception{load();knownScenes();bonusJourney();ads();missionsAndBoosts();coordinatesAndNegatives();graphOwnership();System.out.println("Video6662ReplayTest: "+checks+" checks passed; recorded scene/holdout/native pixels, missions/Get/Close/Play, boosts/start, X/ready skip, negatives, sparse ROI and synthetic geometry; actual Android input not tested");}
}
